head.script:
var log = function(msg) {
    $p.top().scwin.log(msg);
};

scwin.onpageload = function() {
    log("[Demo] 페이지 로드 완료");
    // 샘플 데이터 설정
    var dm = $p.getComponentById("dma_request");
    dm.set("orderId", "ORD-2026-001");
    dm.set("amount", "150000");
};

// =============================================
// [테스트 1] 정상 채널 이벤트
// =============================================
scwin.mfec_normal_onrequest = function(message) {
    log("[T1-E1] onrequest: 메시지 전송 준비 (orderId=" + message.data.orderId + ")");
    return message;
};
scwin.mfec_normal_onerror = function(error) {
    log("[T1-E2] onerror: " + error.errorCode + " - " + error.message);
};
scwin.mfec_normal_onresponse = function(serverObj, response) {
    log("[T1-E6] onresponse: " + serverObj.id + "에서 응답 수신");
};
scwin.mfec_normal_onresponseerror = function(errorPacket) {
    log("[T1-E7] onresponseerror: " + JSON.stringify(errorPacket));
};
scwin.mfec_normal_onresponseall = function() {
    log("[T1-E8] onresponseall: 전체 응답 완료 ✓");
};

// 서버 이벤트
scwin.mfes_order_onbeforeaction = function(message) {
    log("[T1-E3] onbeforeaction: 사전 검증 (amount=" + message.data.amount + ")");
    return true;
};
scwin.mfes_order_onaction = function(message) {
    log("[T1-E4] onaction: 주문 처리 로직 실행");
};
scwin.mfes_order_onactionerror = function(error) {
    log("[T1-E5] onactionerror: " + error.message);
};

// =============================================
// [테스트 2] 서버 부재 채널 이벤트
// =============================================
scwin.mfec_noserver_onrequest = function(message) {
    log("[T2-E1] onrequest: 메시지 전송 준비 (서버 없는 채널)");
    return message;
};
scwin.mfec_noserver_onerror = function(error) {
    log("[T2-E2] onerror 발생!");
    log("        errorCode = " + error.errorCode);
    log("        channelId = " + error.channelId);
    log("        message   = " + error.message);
    if (error.errorCode === "E-NO-SERVER") {
        log("        → 매칭 서버 없음: 후속 처리를 개발자가 자유롭게 구현");
    }
};
scwin.mfec_noserver_onresponseall = function() {
    // 이 이벤트는 E-NO-SERVER 시 호출되지 않아야 함
    log("[T2-E8] onresponseall: (이 로그가 보이면 버그!)");
};

// =============================================
// [테스트 3] E1 취소 이벤트
// =============================================
scwin.mfec_cancel_onrequest = function(message) {
    log("[T3-E1] onrequest: false 반환하여 전송 취소");
    return false;
};
scwin.mfec_cancel_onerror = function(error) {
    // E1에서 취소하면 onerror도 발생하지 않아야 함
    log("[T3-E2] onerror: (이 로그가 보이면 버그!) " + error.errorCode);
};

// =============================================
// [테스트 4] onerror에서 동적 서버 생성 후 재시도
// =============================================
scwin._retryCount = 0;

scwin.mfec_retry_onrequest = function(message) {
    scwin._retryCount++;
    log("[T4-E1] onrequest: 시도 #" + scwin._retryCount);
    return message;
};
scwin.mfec_retry_onerror = function(error) {
    if (error.errorCode === "E-NO-SERVER" && scwin._retryCount < 2) {
        log("[T4-E2] onerror: E-NO-SERVER → 동적 서버 생성 후 재시도");
        // 동적으로 mfeServer 생성
        $p.createMfeServer({
            "id": "mfes_dynamic",
            "channelId": "ch_dynamic",
            "ev:onaction": "scwin.mfes_dynamic_onaction"
        });
        // 재호출
        $p.executeMfe("mfec_retry");
    } else if (error.errorCode === "E-NO-SERVER") {
        log("[T4-E2] onerror: 재시도 초과 — 최종 실패 처리");
    } else {
        log("[T4-E2] onerror: " + error.message);
    }
};
scwin.mfec_retry_onresponse = function(serverObj, response) {
    log("[T4-E6] onresponse: " + serverObj.id + " 응답 수신 (재시도 성공!)");
};
scwin.mfec_retry_onresponseall = function() {
    log("[T4-E8] onresponseall: 전체 응답 완료 ✓ (재시도 성공!)");
};

// 동적 생성 서버 이벤트
scwin.mfes_dynamic_onaction = function(message) {
    log("[T4-E4] onaction(동적 서버): 처리 완료");
};

// =============================================
// 버튼 핸들러
// =============================================
scwin.btn_t1_onclick = function() {
    log("");
    log("━━━ [테스트 1] 정상 채널 호출 (ch_order) ━━━");
    $p.executeMfe("mfec_normal");
};
scwin.btn_t2_onclick = function() {
    log("");
    log("━━━ [테스트 2] 서버 부재 채널 호출 (ch_payment_not_loaded) ━━━");
    $p.executeMfe("mfec_noserver");
};
scwin.btn_t3_onclick = function() {
    log("");
    log("━━━ [테스트 3] E1에서 전송 취소 (ch_payment_not_loaded) ━━━");
    $p.executeMfe("mfec_cancel");
};
scwin.btn_t4_onclick = function() {
    log("");
    log("━━━ [테스트 4] onerror에서 동적 서버 생성 + 재시도 (ch_dynamic) ━━━");
    scwin._retryCount = 0;
    $p.executeMfe("mfec_retry");
};
scwin.btn_all_onclick = async function() {
    log("");
    log("════════════════════════════════════════");
    log("  전체 테스트 순차 실행");
    log("════════════════════════════════════════");

    scwin.btn_t1_onclick();
    // 비동기 이벤트 완료 대기
    await new Promise(function(r) { setTimeout(r, 500); });

    scwin.btn_t2_onclick();
    await new Promise(function(r) { setTimeout(r, 500); });

    scwin.btn_t3_onclick();
    await new Promise(function(r) { setTimeout(r, 500); });

    scwin.btn_t4_onclick();
};
